function initDraw(){let c=$('#drawCanvas'),ctx=c.getContext('2d'),undo=[],redo=[],tool='pencil',drawing=false,last;function resize(){let old=c.toDataURL(),r=c.getBoundingClientRect();c.width=r.width*devicePixelRatio;c.height=r.height*devicePixelRatio;ctx.scale(devicePixelRatio,devicePixelRatio);if(old){let im=new Image();im.onload=()=>ctx.drawImage(im,0,0,r.width,r.height);im.src=old}}resize();let saved=store.get('drawing',null);if(saved){let im=new Image();im.onload=()=>ctx.drawImage(im,0,0,c.clientWidth,c.clientHeight);im.src=saved}function snap(){undo.push(c.toDataURL());if(undo.length>20)undo.shift();redo=[]}function pos(e){let r=c.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}function start(e){e.preventDefault();snap();drawing=true;last=pos(e);c.setPointerCapture(e.pointerId)}function move(e){if(!drawing)return;let p=pos(e);ctx.lineWidth=tool==='eraser'?24:4;ctx.lineCap='round';ctx.strokeStyle=tool==='eraser'?'#fff':'#c76d94';ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();last=p}function end(){drawing=false}c.addEventListener('pointerdown',start);c.addEventListener('pointermove',move);c.addEventListener('pointerup',end);$$('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;$$('[data-tool]').forEach(x=>x.classList.toggle('active',x===b))});function load(data){let im=new Image();im.onload=()=>{ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,c.clientWidth,c.clientHeight)};im.src=data}$('#undo').onclick=()=>{if(undo.length){redo.push(c.toDataURL());load(undo.pop())}};$('#redo').onclick=()=>{if(redo.length){undo.push(c.toDataURL());load(redo.pop())}};$('#clearDraw').onclick=()=>{snap();ctx.clearRect(0,0,c.width,c.height)};$('#saveDraw').onclick=()=>saveDrawing();drawState={c};}
