 breathe(stage){stage.innerHTML='<div class="breath-circle"><div id="breathWord">Ready?<b>🌸</b><small>Press Start</small></div></div><div><button type="button" class="primary" id="bStart">Start</button><button type="button" class="secondary" id="bPause">Pause</button><button type="button" class="secondary" id="bRestart">Restart</button></div>';let phases=[['Breathe In',4,1],['Hold',2,1],['Breathe Out',6,0]],p=0,left=4,timer,paused=false,cycles=0,circle=$('.breath-circle');function paint(){let [word,secs,scale]=phases[p];$('#breathWord').innerHTML=`${word}<b>${left}</b><small>${paused?'Paused':word}</small>`;circle.style.transform=`scale(${scale?1.3:1})`}function tick(){if(!document.getElementById('breathWord')){clearInterval(timer);return}if(paused)return;paint();left--;if(left<0){p=(p+1)%3;left=phases[p][1];if(p===0&&++cycles===3){clearInterval(timer);$('#breathWord').innerHTML='🌸<b>Done</b><small>You gave yourself a moment to breathe.</small>';return}}}function start(){clearInterval(timer);p=0;left=4;cycles=0;paused=false;tick();timer=setInterval(tick,1000)}$('#bStart').onclick=start;$('#bPause').onclick=()=>{paused=!paused;$('#bPause').textContent=paused?'Resume':'Pause';paint()};$('#bRestart').onclick=start},
