const verses=['“Come to me, all you who are weary and burdened, and I will give you rest.” — Matthew 11:28','“Be still, and know that I am God.” — Psalm 46:10','“Cast all your anxiety on him because he cares for you.” — 1 Peter 5:7','“The Lord is my shepherd; I lack nothing.” — Psalm 23:1','“Trust in the Lord with all your heart.” — Proverbs 3:5','“God is our refuge and strength, an ever-present help in trouble.” — Psalm 46:1','“My peace I give you.” — John 14:27','“Those who hope in the Lord will renew their strength.” — Isaiah 40:31'];let currentVerse=verses[0];function showVerse(){$('#verseText').textContent=currentVerse}showVerse();$('#newVerse').onclick=()=>{currentVerse=verses[Math.floor(Math.random()*verses.length)];showVerse()};$('#saveVerse').onclick=()=>{let a=store.get('verses',[]);if(!a.includes(currentVerse))a.push(currentVerse);store.set('verses',a);renderSaved()};function renderSaved(){$('#savedVerses').innerHTML=store.get('verses',[]).map(v=>`<p>🤍 ${v}</p>`).join('')}renderSaved();
const prayers={Stress:'God, meet me in this busy feeling. Help me take this moment one breath at a time. Amen.',School:'God, give me a clear mind and a gentle heart as I learn today. Amen.',Fear:'God, stay close when I feel afraid. Remind me I do not carry this alone. Amen.',Uncertainty:'God, hold what I cannot figure out. Help me trust your next small step. Amen.',Gratitude:'Thank you, God, for the quiet good things around me today. Amen.',Strength:'God, lend me your strength for just this moment. Amen.',Rest:'God, let my mind and body rest in your care. Amen.',Hope:'God, plant a small bright hope in me today. Amen.'};let type='Stress';$('#prayerTypes').innerHTML=Object.keys(prayers).map(x=>`<button type="button" data-prayer="${x}">${x}</button>`).join('');function showPrayer(){$('#prayerText').textContent=prayers[type]}showPrayer();$$('[data-prayer]').forEach(b=>b.onclick=()=>{type=b.dataset.prayer;showPrayer()});$('#newPrayer').onclick=()=>{type=Object.keys(prayers)[Math.floor(Math.random()*8)];showPrayer()};
const notes=['You are allowed to take up soft space.','Small progress is still a kind of progress.','You do not have to earn rest.','A slow day can still be a meaningful day.','You can begin again, gently.','There is no rush in becoming.','You are doing more than you think.','This feeling is a visitor, not your whole story.','Take the next kind step, not every step.','Your heart deserves patience too.','You are safe to pause.','One breath can be a fresh beginning.','You are not behind in your own life.','Let today be little if it needs to be.','Quiet moments count.','You are held, even in the messy parts.','Be as kind to yourself as you are to others.','The sun will find you again.','You can put down what is too heavy for today.','You matter without performing.','Your softness is not a weakness.','You have made it through every hard day so far.','You are allowed to change your mind.','Tiny joys are real joys.','Your pace is enough.','You can make room for hope.','Being here is enough for now.','There is grace for this moment.','You are allowed a fresh page.','Take good care of your tender heart.'];let note=0;function showNote(){$('#noteText').textContent=notes[note]}showNote();$('#newNote').onclick=()=>{note=(note+1)%notes.length;showNote()};
let resetSeconds=300,resetTimer=null;function renderReset(){let m=Math.floor(resetSeconds/60),s=resetSeconds%60,minute=Math.min(5,5-Math.floor((300-resetSeconds)/60));$('#resetClock').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;$('#resetText').textContent=resetSeconds===0?'You gave yourself five minutes. That matters. 🤍':['Breathe.','Relax your shoulders.','Look around you.','Think of one thing you’re grateful for.','Pray or sit quietly.'][Math.max(0,minute-1)]}function startReset(){clearInterval(resetTimer);resetTimer=setInterval(()=>{if(resetSeconds>0){resetSeconds--;renderReset()}else clearInterval(resetTimer)},1000)}$('#resetStart').onclick=startReset;$('#resetPause').onclick=()=>clearInterval(resetTimer);$('#resetRestart').onclick=()=>{clearInterval(resetTimer);resetSeconds=300;renderReset()};renderReset();
