const fruitKey='little-rest-fruit-v1';
const getFruitLog=()=>store.get(fruitKey,{});
const saveFruitEntry=(name,patch)=>{let log=getFruitLog();log[name]={...(log[name]||{reflection:'',step:'',done:false}),...patch,at:Date.now()};store.set(fruitKey,log);return log[name]};
gameFns.fruit=stage=>{
 const rail=active=>`<ol class="fruit-rail">${['Choose','God’s Word','Reflect','Small step','Grow'].map((label,i)=>`<li class="${i<active?'done':''}${i===active?' now':''}">${label}</li>`).join('')}</ol>`;
 const tree=()=>{let log=getFruitLog(),grown=Object.keys(log).filter(k=>log[k].done);return `<div class="fruit-tree"><span class="fruit-tree-canopy">🌳</span><span class="fruit-tree-crop">${grown.map(k=>(fruitContent.find(f=>f.name===k)||{}).icon||'').join('')}</span></div><p class="fruit-tree-note">${grown.length?`${grown.length} fruit${grown.length>1?'s':''} growing here: ${escapeHTML(grown.join(', '))}.`:'Your tree is bare for now, and that is a perfectly good place to start.'}</p>`};

 function chooser(){
  let log=getFruitLog();
  stage.innerHTML=`<div class="fruit-view">${rail(0)}<h3 class="fruit-ask">What fruit do you want to bear today?</h3><p class="fruit-sub">Pick the one you need most. There is no wrong answer, and you can change it whenever you like.</p><div class="fruit-choices">${fruitContent.map((f,i)=>`<button type="button" data-fruit="${i}" class="${log[f.name]&&log[f.name].done?'grown':''}">${f.icon}<small>${f.name}</small></button>`).join('')}</div>${tree()}</div>`;
  $$('[data-fruit]').forEach(b=>b.onclick=()=>reflect(+b.dataset.fruit));
 }

 function reflect(index){
  let f=fruitContent[index],saved=getFruitLog()[f.name]||{reflection:'',step:'',done:false};
  stage.innerHTML=`<div class="fruit-view fruit-detail">${rail(saved.done?4:1)}<div class="fruit-crest"><span>${f.icon}</span><div><p class="fruit-eyebrow">Your fruit today</p><h3>${f.name}</h3></div></div><p class="fruit-desc">${escapeHTML(f.desc)}</p><section class="fruit-block fruit-verse"><h4>📖 Bible verse</h4><blockquote>${escapeHTML(f.verse)}</blockquote><cite>— ${escapeHTML(f.ref)}</cite></section><section class="fruit-block"><h4>🌱 How can you grow this fruit today?</h4><ul class="fruit-grow">${f.grow.map(g=>`<li>${escapeHTML(g)}</li>`).join('')}</ul></section><section class="fruit-block"><h4>💭 Reflection</h4><p class="fruit-question">${escapeHTML(f.question)}</p><textarea id="fruitReflection" rows="3" maxlength="600" placeholder="You can write as little as you like — or nothing at all.">${escapeHTML(saved.reflection||'')}</textarea><small id="fruitReflectionMsg" aria-live="polite">${saved.reflection?'Saved on this device.':'Optional. Saved only on this device.'}</small></section><section class="fruit-block"><h4>✨ My small step today</h4><div class="suggestion-chips fruit-steps">${f.steps.map(s=>`<button type="button" data-step="${escapeHTML(s)}" class="${saved.step===s?'chosen':''}">${escapeHTML(s)}</button>`).join('')}</div><div class="idea-entry"><input id="fruitStep" maxlength="160" autocomplete="off" placeholder="Or write your own small step…" value="${escapeHTML(saved.step||'')}"><button type="button" class="secondary" id="fruitStepSave">Save step</button></div><small id="fruitStepMsg" aria-live="polite">${saved.step?'Your step is saved.':''}</small></section><div class="fruit-actions"><button type="button" class="primary" id="fruitDone"${saved.done?' disabled':''}>${saved.done?'✓ Done today':'✓ I did my small step'}</button><button type="button" class="text-btn" id="fruitBack">← Choose another fruit</button></div><p class="fruit-feedback" id="fruitFeedback" aria-live="polite">${saved.done?escapeHTML(f.done):''}</p>${tree()}</div>`;

  let reflection=$('#fruitReflection');
  reflection.addEventListener('input',()=>{saveFruitEntry(f.name,{reflection:reflection.value});$('#fruitReflectionMsg').textContent='Saved on this device.'});
  const setStep=value=>{saveFruitEntry(f.name,{step:value});$('#fruitStep').value=value;$('#fruitStepMsg').textContent=value?'Your step is saved.':'';$$('[data-step]').forEach(x=>x.classList.toggle('chosen',x.dataset.step===value))};
  $$('[data-step]').forEach(b=>b.onclick=()=>setStep(b.dataset.step===$('#fruitStep').value?'':b.dataset.step));
  $('#fruitStepSave').onclick=()=>setStep($('#fruitStep').value.trim());
  $('#fruitStep').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();setStep($('#fruitStep').value.trim())}};
  $('#fruitDone').onclick=()=>{
   let step=$('#fruitStep').value.trim();
   saveFruitEntry(f.name,{done:true,step:step,reflection:reflection.value});
   $('#fruitDone').disabled=true;$('#fruitDone').textContent='✓ Done today';
   $('#fruitFeedback').textContent=f.done+(step?' You said: “'+step+'”':'');
   let crop=stage.querySelector('.fruit-tree-crop');if(crop&&!crop.textContent.includes(f.icon))crop.textContent+=f.icon;
   $$('.fruit-rail li').forEach((li,i)=>{li.classList.toggle('done',i<4);li.classList.toggle('now',i===4)});
  };
  $('#fruitBack').onclick=chooser;
 }
 chooser();
};
/* Leave It Behind: putting things down. Items are kept until the person clears them. */
const leaveKey='little-rest-leave-v1';
const getLeave=()=>({items:[],space:[],...store.get(leaveKey,{items:[],space:[]})});
const saveLeave=data=>store.set(leaveKey,data);
gameFns.leave=stage=>{
 const spaceIdeas=['🕊️ Peace','😴 Rest','🌤️ Hope','😊 Joy','🦁 Courage','🤍 Kindness to myself'];
 function render(){
  let data=getLeave(),carried=data.items.filter(x=>!x.away),away=data.items.filter(x=>x.away);
  stage.innerHTML=`<div class="leave-view">
   <h3 class="leave-ask">What do you want to leave behind today?</h3>
   <p class="leave-sub">Add as many as you need. Drag one into the bag, or just tap <b>Put it away</b> — both work.</p>
   <div class="idea-entry"><input id="leaveInput" maxlength="160" autocomplete="off" placeholder="Overthinking, fear, pressure, a heavy memory…"><button type="button" class="primary" id="leaveAdd">+ Add</button></div>
   <div class="suggestion-chips leave-suggest">${['Overthinking','Fear','Stress','Regret','Self-doubt','Pressure','Comparison','Negative thoughts'].map(s=>`<button type="button" data-leave-suggest="${s}">${s}</button>`).join('')}</div>
   <div class="leave-stage" id="leaveStage">
    <div class="leave-carry"><p class="leave-label">Things you are carrying</p><div class="leave-items" id="leaveItems">${carried.length?carried.map(x=>`<span class="leave-item" data-item="${x.id}"><b>${escapeHTML(x.text)}</b><button type="button" class="leave-away" data-away="${x.id}">Put it away</button><button type="button" class="leave-drop" data-forget="${x.id}" aria-label="Remove ${escapeHTML(x.text)}">×</button></span>`).join(''):'<small class="leave-empty">Nothing added yet.</small>'}</div></div>
    <div class="leave-bag" id="leaveBag"><span class="leave-bag-art">${away.length?'🎒':'🗑️'}</span><small>${away.length?`${away.length} put away`:'The bag'}</small></div>
   </div>
   ${away.length?`<div class="leave-inside"><p class="leave-label">Already put down <button type="button" class="text-btn" id="leaveShow">${data.open?'Hide':'Show'}</button></p>${data.open?`<div class="leave-items">${away.map(x=>`<span class="leave-item is-away"><b>${escapeHTML(x.text)}</b><button type="button" class="leave-away" data-back="${x.id}">Pick it back up</button></span>`).join('')}</div>`:'<small class="leave-empty">Kept quietly, only on this device.</small>'}</div>`:''}
   <p class="leave-msg" id="leaveMsg" aria-live="polite">${away.length?'You don’t have to carry everything with you. 💗':''}</p>
   ${away.length?`<section class="fruit-block leave-space"><h4>🌤️ What would you like to make space for instead?</h4><div class="suggestion-chips">${spaceIdeas.map(s=>`<button type="button" data-space="${escapeHTML(s)}" class="${data.space.includes(s)?'chosen':''}">${escapeHTML(s)}</button>`).join('')}</div><div class="idea-entry"><input id="spaceInput" maxlength="120" autocomplete="off" placeholder="Or say it in your own words…"><button type="button" class="secondary" id="spaceAdd">+ Add</button></div><p class="leave-space-list">${data.space.length?data.space.map(s=>`<span class="idea-tag is-static">${escapeHTML(s)}</span>`).join(''):''}</p></section>`:''}
   <div class="leave-actions"><button type="button" class="text-btn" id="leavePrivate">🔒 Keep this private</button><button type="button" class="text-btn" id="leaveReset">↺ Start again</button><button type="button" class="text-btn" id="leaveClear">🧹 Clear everything</button></div>
  </div>`;

  const add=text=>{let clean=String(text).trim();if(!clean)return;let d=getLeave();if(!d.items.some(x=>x.text.toLowerCase()===clean.toLowerCase()&&!x.away))d.items.push({id:'l'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),text:clean,away:false});saveLeave(d);render()};
  $('#leaveAdd').onclick=()=>add($('#leaveInput').value);
  $('#leaveInput').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();add($('#leaveInput').value)}};
  $$('[data-leave-suggest]').forEach(b=>b.onclick=()=>add(b.dataset.leaveSuggest));

  const putAway=id=>{let d=getLeave(),item=d.items.find(x=>x.id===id);if(!item)return;item.away=true;d.open=false;saveLeave(d);render();$('#leaveMsg').textContent='You don’t have to carry everything with you. 💗'};
  $$('[data-away]').forEach(b=>b.onclick=()=>putAway(b.dataset.away));
  $$('[data-back]').forEach(b=>b.onclick=()=>{let d=getLeave(),item=d.items.find(x=>x.id===b.dataset.back);if(item)item.away=false;saveLeave(d);render()});
  $$('[data-forget]').forEach(b=>b.onclick=()=>{let d=getLeave();d.items=d.items.filter(x=>x.id!==b.dataset.forget);saveLeave(d);render()});

  /* Dragging is the desktop path; every item also has its own tap button above. */
  let bag=$('#leaveBag'),area=$('#leaveStage');
  $$('#leaveItems .leave-item').forEach(el=>drag(el,area,node=>{
   let a=node.getBoundingClientRect(),b=bag.getBoundingClientRect();
   if(a.left<b.right&&a.right>b.left&&a.top<b.bottom&&a.bottom>b.top)putAway(node.dataset.item);
   else{node.style.position='';node.style.left='';node.style.top=''}
  }));

  if($('#leaveShow'))$('#leaveShow').onclick=()=>{let d=getLeave();d.open=!d.open;saveLeave(d);render()};
  if($('#spaceAdd')){
   const addSpace=text=>{let clean=String(text).trim();if(!clean)return;let d=getLeave();if(!d.space.includes(clean))d.space.push(clean);saveLeave(d);render()};
   $('#spaceAdd').onclick=()=>addSpace($('#spaceInput').value);
   $('#spaceInput').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();addSpace($('#spaceInput').value)}};
   $$('[data-space]').forEach(b=>b.onclick=()=>{let d=getLeave(),s=b.dataset.space;d.space=d.space.includes(s)?d.space.filter(x=>x!==s):[...d.space,s];saveLeave(d);render()});
  }
  $('#leavePrivate').onclick=()=>{$('#leaveMsg').textContent='Nothing here leaves this device. It is only saved in this browser, and only you can see it. 🔒'};
  $('#leaveReset').onclick=()=>{let d=getLeave();d.items.forEach(x=>x.away=false);d.open=false;saveLeave(d);render();$('#leaveMsg').textContent='Everything is back out. You can put things down again whenever you want.'};
  $('#leaveClear').onclick=()=>{if(confirm('Clear everything you have written here? This cannot be undone.')){saveLeave({items:[],space:[]});render()}};
 }
 render();
};
/* Let It Go: a single thought, written down and then released. Nothing here is ever stored. */
gameFns.letgo=stage=>{
 const closings=['You are allowed to release what you cannot change.','You don’t have to hold onto every painful thought.','It was heavy. You are allowed to set it down.','Letting go is not giving up. It is making room.'];
 function write(previous){
  stage.innerHTML=`<div class="letgo-view">
   <h3 class="letgo-ask">Write something you are ready to let go of.</h3>
   <p class="letgo-sub">A worry, a regret, something you keep replaying. This is a digital-only moment — nothing is burned in real life, and nothing you write here is saved.</p>
   <div class="letgo-writing"><textarea id="letgoText" rows="3" maxlength="300" placeholder="I’m afraid of disappointing everyone…">${escapeHTML(previous||'')}</textarea></div>
   <button type="button" class="primary" id="letgoMake">Put it on a note →</button>
  </div>`;
  $('#letgoMake').onclick=()=>{let value=$('#letgoText').value.trim();if(!value){$('#letgoText').focus({preventScroll:true});return}preview(value)};
 }
 function preview(text){
  stage.innerHTML=`<div class="letgo-view">
   <p class="letgo-sub">Here it is, out of your head and onto the page. When you are ready, you can let it go.</p>
   <div class="letgo-scene"><div class="letgo-note" id="letgoNote"><span>${escapeHTML(text)}</span></div><div class="letgo-embers" id="letgoEmbers" aria-hidden="true"></div></div>
   <div class="button-row"><button type="button" class="primary letgo-burn" id="letgoRelease">🔥 Let it go</button><button type="button" class="text-btn" id="letgoEdit">✎ Change what it says</button></div>
  </div>`;
  $('#letgoEdit').onclick=()=>write(text);
  $('#letgoRelease').onclick=()=>{
   let note=$('#letgoNote'),embers=$('#letgoEmbers'),button=$('#letgoRelease');
   button.disabled=true;$('#letgoEdit').disabled=true;
   for(let i=0;i<14;i++){let e=document.createElement('i');e.className='letgo-ember';e.style.left=(8+Math.random()*84)+'%';e.style.animationDelay=(Math.random()*.7)+'s';embers.append(e)}
   note.classList.add('is-releasing');
   /* Matches the .is-releasing animation; reduced-motion users simply get there sooner. */
   let wait=matchMedia('(prefers-reduced-motion: reduce)').matches?300:2200;
   setTimeout(()=>released(),wait);
  };
 }
 function released(){
  stage.innerHTML=`<div class="letgo-view letgo-after">
   <div class="letgo-calm">🕊️</div>
   <h3>${closings[Math.floor(Math.random()*closings.length)]}</h3>
   <p class="letgo-sub">It is gone from this page, and it was never saved anywhere.</p>
   <div class="button-row"><button type="button" class="primary" id="letgoAgain">✎ Write another</button><button type="button" class="secondary" id="letgoBreathe">🌬 Take a breath</button><button type="button" class="text-btn" id="letgoHome">🏠 Return home</button></div>
  </div>`;
  $('#letgoAgain').onclick=()=>write('');
  $('#letgoBreathe').onclick=()=>openGame('breathe');
  $('#letgoHome').onclick=()=>{closeModal();go('home')};
 }
 write('');
};
